// Independent complete cold/warm observations; no unobserved warming work.
import {readFileSync} from 'node:fs';
import {Hash,createHash} from 'node:crypto';
import {repositorySourceURL} from './repository-paths.mjs';
import {resolveModuleGraph} from '../../project.mjs';
import {PRODUCTION_PROFILE} from '../../cfg-profile.mjs';
import {createWholeOwnerCoreAdoptionProducerContext,createEnclosingCoreAdoptionProducerContext,coreAdoptionProducerClosedAttributeSpans,coreAdoptionProducerBindings,finishCoreAdoptionProducerContext,captureWholeOwnerCoreAdoptionAttributeData} from '../../whole-owner-core-producer-candidate.mjs';
import {encodeCompleteHookWire} from './complete-hook-wire.mjs';
const root=new URL('../../../../',import.meta.url),dependencyInputs={manifest:readFileSync(repositorySourceURL('Cargo.toml',root),'utf8'),lock:readFileSync(repositorySourceURL('Cargo.lock',root),'utf8')},json=JSON.stringify,get=Object.getOwnPropertyDescriptor,define=Object.defineProperty,apply=Reflect.apply,mode=process.argv[2],kind=process.argv[3];if(!['legacy','whole'].includes(mode)||!['json-hook','hash-hook'].includes(kind)||process.argv.length!==4)throw TypeError('Complete legacy|whole JSON|Hash Core fixture required');
const creator=mode==='legacy'?createEnclosingCoreAdoptionProducerContext:createWholeOwnerCoreAdoptionProducerContext;
function setup(){const sources=new Map([['src/lib.rs','mod model;'],['src/model.rs','#[derive(Clone)]pub struct Empty;']]),graph=resolveModuleGraph({entry:'src/lib.rs',paths:[...sources.keys()],readSource:path=>sources.get(path),compilationProfile:PRODUCTION_PROFILE}),options={modules:graph.modules,compilationProfile:PRODUCTION_PROFILE,dependencyInputs};return {options,context:creator(options)};}
function inspect({options,context}){if(mode==='whole')return captureWholeOwnerCoreAdoptionAttributeData(context);return JSON.stringify({schema:'whole-owner-core-attribute-inspection-data-v1',modules:options.modules.map(module=>({file:module.file,module:[...module.path],source:module.source,sourceSha256:createHash('sha256').update(module.source).digest('hex'),sourceViewDigest:module.sourceView?.digest??null,configurationCondition:module.configurationCondition??null,attributes:coreAdoptionProducerClosedAttributeSpans(context,module)})),producerEffects:finishCoreAdoptionProducerContext(context),sourceAuthority:false,runtimeAuthority:false});}
function outcome(run){try{return {value:run()};}catch(error){return {error:{name:error.name,message:error.message}};}}
function observe(run,observation=kind){const stringify=get(JSON,'stringify'),update=get(Hash.prototype,'update'),digest=get(Hash.prototype,'digest'),tape=[];try{if(observation==='json-hook')define(JSON,'stringify',{...stringify,value:function(...args){const value=apply(stringify.value,this,args);tape[tape.length]={operation:'JSON.stringify',args:apply(json,JSON,[args]),value};return value;}});else{define(Hash.prototype,'update',{...update,value:function(...args){tape[tape.length]={operation:'Hash.update',args};return apply(update.value,this,args);}});define(Hash.prototype,'digest',{...digest,value:function(...args){const value=apply(digest.value,this,args);tape[tape.length]={operation:'Hash.digest',args,value};return value;}});}return {result:outcome(run),tape};}finally{define(JSON,'stringify',stringify);define(Hash.prototype,'update',update);define(Hash.prototype,'digest',digest);}}
let first;const workloads=[];workloads.push({state:'cold-complete-Core-creation-and-inspection',...observe(()=>{first=setup();return {bindings:coreAdoptionProducerBindings(first.context),data:inspect(first)};})});workloads.push({state:'warm-fresh-complete-Core-creation-and-inspection',...observe(()=>{const next=setup();return {bindings:coreAdoptionProducerBindings(next.context),data:inspect(next)};})});
// JSON's original native-CST ingress refuses before creating a context. Keep
// both failed workloads, then explicitly observe ALL real initialization Hash
// work so the unchanged third inspection never uses an undefined placeholder.
const initialization=kind==='json-hook'?{state:'explicit-observed-Hash-initialization-for-JSON-inspection',...observe(()=>{first=setup();return {bindings:coreAdoptionProducerBindings(first.context)};},'hash-hook')}:null;
workloads.push({state:'same-context-complete-Core-inspection',...observe(()=>inspect(first))});process.stdout.write(encodeCompleteHookWire({schema:'complete-whole-owner-core-hook-wire-v1',kind,engine:{execPath:process.execPath,node:process.versions.node,bun:process.versions.bun??null},initialization,workloads}));
